    for s in range(6):
        c=np.concatenate([[0],stats.t.cdf(np.array(cuts)-locs[k][s],df,scale=sc),[1]]);P[s]=np.diff(c)
    Lk.append(P)
def ev(b): return float(b@pay)
def post(b,k,o):
    x=b*Lk[k][:,o];return x
@functools.lru_cache(None)
def V(b,d):
