    for k in range(3):
        tot=0
        for o in range(6):
            x=post(b,k,o);p=x.sum()
            if p>1e-12: tot+=p*V(tuple(np.round(x/p,6)),2)
        res[names[k]]=round(tot-20-base,1)
    print('VOI',res,'->',('check '+max(res,key=res.get)) if max(res.values())>0 else ('approve' if ev(b)>0 else 'decline'))
